window.tinyMCE.PluginManager.add('csucsplusz_shortcodes', function (editor) {
  editor.addButton('price_shortcodes', {
    text: 'Árak',
    type: 'menubutton',
    menu: window.priceNames.map(price => ({
      text: price,
      onclick: function () {
        editor.insertContent(`[ár="${price}"]`)
      }
    }))
  })

  editor.addButton('contact_shortcodes', {
    text: 'Elérhetőségek',
    type: 'menubutton',
    menu: window.contacts.map(contact => ({
      text: contact,
      onclick: function () {
        editor.insertContent(`[${contact}]`)
      }
    }))
  })

  editor.addButton('copy_content_shortcode', {
    text: 'Másolható szöveg',
    onclick: function () {
      const selected = editor.selection.getContent()
      if (!selected) {
        editor.insertContent('[másolható szöveg=""]')
        return
      }
      
      editor.insertContent(`[másolható szöveg="${selected}"]`)
    }
  })
})